// Package agg aggregates per endpoint request latency for a service that serves a few
// thousand requests a second across a handful of endpoints.
//
// One Registry is shared by every request goroutine and by the exporter goroutine that
// scrapes it once a second. Observe is on the request path. Snapshot, SnapshotAll,
// Endpoints and Observed are on the exporter's path. Neither path is allowed to make the
// other wait longer than it has to, and two exporter reads of the same endpoint must be
// able to run at the same time: quantile walks the histogram in place, so a read is not
// cheap and serialising reads behind one lock turns a one second scrape into a stall.
//
// This started life single threaded. A mutex was added later, around the map, which is
// where it stopped.
package agg

import (
	"sort"
	"sync"
)

// Stat is the aggregate view of one endpoint.
type Stat struct {
	Count       int64
	TotalMicros int64
	MaxMicros   int64
	P95Micros   int64
}

// MeanMicros returns the mean latency in microseconds, or zero when nothing has been
// recorded for the endpoint.
func (s Stat) MeanMicros() int64 {
	if s.Count == 0 {
		return 0
	}
	return s.TotalMicros / s.Count
}

// bucket holds the running aggregate for one endpoint.
type bucket struct {
	hist        histogram
	count       int64
	totalMicros int64
	maxMicros   int64
}

// Registry holds one bucket per endpoint.
type Registry struct {
	mu      sync.Mutex
	buckets map[string]*bucket

	// observed counts every call to Observe, across all endpoints.
	observed int64

	// hotName and hot cache the bucket for the endpoint seen most recently. In a real
	// process nearly every call arrives for the same endpoint as the one before it, so
	// this skips the map lookup for the common case.
	hotName string
	hot     *bucket
}

// New returns an empty registry.
func New() *Registry {
	return &Registry{buckets: make(map[string]*bucket)}
}

// Observe records one request against an endpoint.
func (r *Registry) Observe(endpoint string, micros int64) {
	b := r.lookup(endpoint)
	b.count++
	b.totalMicros += micros
	if micros > b.maxMicros {
		b.maxMicros = micros
	}
	b.hist.observe(micros)
	r.observed++
}

// lookup returns the bucket for an endpoint, creating it the first time it is seen.
func (r *Registry) lookup(endpoint string) *bucket {
	if r.hot != nil && endpoint == r.hotName {
		return r.hot
	}
	r.mu.Lock()
	b := r.buckets[endpoint]
	if b == nil {
		b = &bucket{}
		r.buckets[endpoint] = b
	}
	r.mu.Unlock()
	r.hotName = endpoint
	r.hot = b
	return b
}

// Snapshot returns the aggregate for one endpoint, and false when the endpoint has never
// been observed.
func (r *Registry) Snapshot(endpoint string) (Stat, bool) {
	r.mu.Lock()
	b := r.buckets[endpoint]
	r.mu.Unlock()
	if b == nil {
		return Stat{}, false
	}
	return Stat{
		Count:       b.count,
		TotalMicros: b.totalMicros,
		MaxMicros:   b.maxMicros,
		P95Micros:   b.hist.quantile(0.95),
	}, true
}

// SnapshotAll returns the aggregate for every endpoint seen so far.
func (r *Registry) SnapshotAll() map[string]Stat {
	names := r.Endpoints()
	out := make(map[string]Stat, len(names))
	for _, name := range names {
		if stat, ok := r.Snapshot(name); ok {
			out[name] = stat
		}
	}
	return out
}

// Endpoints returns every endpoint seen so far, sorted.
func (r *Registry) Endpoints() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	names := make([]string, 0, len(r.buckets))
	for name := range r.buckets {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

// Observed returns the number of Observe calls the registry has taken.
func (r *Registry) Observed() int64 {
	return r.observed
}

// Reset drops every recorded sample. The exporter calls it after a successful publish.
func (r *Registry) Reset() {
	r.mu.Lock()
	r.buckets = make(map[string]*bucket)
	r.observed = 0
	r.mu.Unlock()
}

package agg

import (
	"math"
	"time"
)

// bucketCount buckets cover one microsecond to just over eight seconds, in powers of two.
const bucketCount = 24

// quantileCost stands in for the interpolation pass the real exporter runs across the
// buckets and the reservoir it keeps beside them.
//
// It is a sleep rather than a busy loop on purpose. What matters about the read path is
// whether two readers can be inside it at the same time, and a busy loop would measure
// how many cores the box has instead.
const quantileCost = 8 * time.Millisecond

// histogram is a fixed bucket latency histogram. Bucket i counts samples below 1<<i
// microseconds.
//
// It carries no lock of its own, deliberately. Whatever owns a histogram owns its
// synchronisation: observe mutates it, quantile reads it, and a caller that runs quantile
// without holding the lock observe takes has a data race whether or not the numbers come
// out looking right.
type histogram struct {
	buckets [bucketCount]uint32
	count   uint64
}

// observe files one sample.
func (h *histogram) observe(micros int64) {
	h.buckets[bucketFor(micros)]++
	h.count++
}

// quantile returns the upper bound, in microseconds, of the bucket holding the q-th
// sample, or zero when nothing has been filed yet.
func (h *histogram) quantile(q float64) int64 {
	time.Sleep(quantileCost)
	if h.count == 0 {
		return 0
	}
	target := uint64(math.Ceil(q * float64(h.count)))
	if target == 0 {
		target = 1
	}
	var seen uint64
	for i := 0; i < bucketCount; i++ {
		seen += uint64(h.buckets[i])
		if seen >= target {
			return int64(1) << uint(i)
		}
	}
	return int64(1) << uint(bucketCount-1)
}

// bucketFor returns the index of the bucket a sample belongs in.
func bucketFor(micros int64) int {
	index := 0
	for index < bucketCount-1 && micros >= int64(1)<<uint(index) {
		index++
	}
	return index
}

package agg_test

import (
	"fmt"
	"sync"
	"testing"

	"example.internal/aggregator/agg"
)

func TestObserveThenSnapshot(t *testing.T) {
	r := agg.New()
	for i := 0; i < 10; i++ {
		r.Observe("/v1/checkout", 900)
	}
	r.Observe("/v1/cart", 120)

	stat, ok := r.Snapshot("/v1/checkout")
	if !ok {
		t.Fatal("/v1/checkout was observed but Snapshot says it does not exist")
	}
	if stat.Count != 10 {
		t.Errorf("Count = %d, want 10", stat.Count)
	}
	if stat.TotalMicros != 9000 {
		t.Errorf("TotalMicros = %d, want 9000", stat.TotalMicros)
	}
	if stat.MaxMicros != 900 {
		t.Errorf("MaxMicros = %d, want 900", stat.MaxMicros)
	}
	if stat.MeanMicros() != 900 {
		t.Errorf("MeanMicros = %d, want 900", stat.MeanMicros())
	}
	// Buckets are powers of two and quantile reports the bucket's upper bound, so ten
	// samples of 900 microseconds put p95 in the bucket that ends at 1024.
	if stat.P95Micros != 1024 {
		t.Errorf("P95Micros = %d, want 1024", stat.P95Micros)
	}
	if r.Observed() != 11 {
		t.Errorf("Observed = %d, want 11", r.Observed())
	}
}

func TestSnapshotAllCoversEveryEndpoint(t *testing.T) {
	r := agg.New()
	r.Observe("/v1/cart", 100)
	r.Observe("/v1/checkout", 200)
	r.Observe("/v1/cart", 300)

	all := r.SnapshotAll()
	if len(all) != 2 {
		t.Fatalf("SnapshotAll returned %d endpoints, want 2", len(all))
	}
	if all["/v1/cart"].Count != 2 || all["/v1/cart"].TotalMicros != 400 {
		t.Errorf("/v1/cart = %+v, want Count 2 and TotalMicros 400", all["/v1/cart"])
	}
	if got := r.Endpoints(); len(got) != 2 || got[0] != "/v1/cart" || got[1] != "/v1/checkout" {
		t.Errorf("Endpoints = %v, want sorted [/v1/cart /v1/checkout]", got)
	}
}

// TestConcurrentObserveKeepsEveryUpdate is the reproduction. Every request goroutine in
// the service calls Observe on the same registry.
func TestConcurrentObserveKeepsEveryUpdate(t *testing.T) {
	const (
		writers = 8
		each    = 250
	)
	endpoints := []string{"/v1/cart", "/v1/checkout", "/v1/inventory", "/v1/orders"}

	r := agg.New()
	var wg sync.WaitGroup
	for w := 0; w < writers; w++ {
		wg.Add(1)
		go func(worker int) {
			defer wg.Done()
			for i := 0; i < each; i++ {
				r.Observe(endpoints[(worker+i)%len(endpoints)], int64(100+i))
			}
		}(w)
	}
	wg.Wait()

	if got, want := r.Observed(), int64(writers*each); got != want {
		t.Errorf("Observed = %d, want %d", got, want)
	}
	var total int64
	for _, name := range endpoints {
		stat, ok := r.Snapshot(name)
		if !ok {
			t.Errorf("%s was observed but is missing from the registry", name)
			continue
		}
		total += stat.Count
	}
	if want := int64(writers * each); total != want {
		t.Errorf("counts across endpoints sum to %d, want %d", total, want)
	}
}

// TestExporterScrapesWhileRequestsLand is the other half of the reproduction: the
// exporter reads while the request path writes.
func TestExporterScrapesWhileRequestsLand(t *testing.T) {
	const (
		writers = 4
		each    = 200
		scrapes = 5
	)

	r := agg.New()
	var wg sync.WaitGroup
	for w := 0; w < writers; w++ {
		wg.Add(1)
		go func(worker int) {
			defer wg.Done()
			name := fmt.Sprintf("/v1/shard-%d", worker)
			for i := 0; i < each; i++ {
				r.Observe(name, int64(200+i))
			}
		}(w)
	}

	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < scrapes; i++ {
			for name, stat := range r.SnapshotAll() {
				if stat.Count < 0 || stat.TotalMicros < 0 {
					t.Errorf("%s scraped a negative aggregate: %+v", name, stat)
				}
			}
		}
	}()
	wg.Wait()

	if got, want := r.Observed(), int64(writers*each); got != want {
		t.Errorf("Observed = %d, want %d", got, want)
	}
}

